await evalJS(`document.querySelector('[data-live]').click()`);
results.push(['switch live',await evalJS(`JSON.stringify({live:JSON.parse(localStorage.senderConfig).liveChannelId,visible:document.querySelector('#tvView').children.length>0})`)]);
await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
